<template><div class="resource-page"><ResourceHeader title="广告策略" description="按当前应用管理广告位、时间窗口和投放权重。" action-text="创建广告" @action="openCreate" /><ElCard shadow="never" class="table-card" v-loading="loading"><div v-if="!ads.length&&!loading" class="empty"><ArtSvgIcon icon="ri:advertisement-line"/><strong>暂无广告策略</strong><span>创建广告后将通过兼容接口投放。</span><ElButton type="primary" @click="openCreate">创建广告</ElButton></div><ElTable v-else :data="ads" stripe><ElTableColumn label="广告内容" min-width="260"><template #default="{row}"><div class="ad"><span class="thumb"></span><div><b>{{row.title}}</b><small>{{row.description||row.adKey}}</small></div></div></template></ElTableColumn><ElTableColumn prop="position" label="广告位" width="140"/><ElTableColumn prop="weight" label="权重" width="80"/><ElTableColumn label="状态" width="100"><template #default="{row}"><ElTag :type="row.published?'success':'info'" effect="light">{{row.published?'投放中':'已暂停'}}</ElTag></template></ElTableColumn><ElTableColumn label="操作" width="150" fixed="right"><template #default="{row}"><ElButton link type="primary" @click="edit(row)">编辑</ElButton><ElButton link type="danger" @click="remove(row)">删除</ElButton></template></ElTableColumn></ElTable></ElCard><ElDialog v-model="dialog" :title="editing?'编辑广告':'创建广告'" width="540px"><ElForm :model="form" label-position="top"><ElFormItem label="广告标识"><ElInput v-model="form.adKey" placeholder="例如 home-2026-autumn"/></ElFormItem><ElFormItem label="标题"><ElInput v-model="form.title"/></ElFormItem><ElFormItem label="广告位"><ElSelect v-model="form.position" class="full"><ElOption label="首页横幅 home-banner" value="home-banner"/><ElOption label="侧边栏 sidebar" value="sidebar"/><ElOption label="弹窗 popup" value="popup"/></ElSelect></ElFormItem><ElFormItem label="图片地址"><ElInput v-model="form.imageUrl" placeholder="https://.../banner.png"/></ElFormItem><ElFormItem label="跳转地址"><ElInput v-model="form.destinationUrl" placeholder="https://..."/></ElFormItem><ElFormItem label="权重"><ElInputNumber v-model="form.weight" :min="0" :max="10000"/></ElFormItem><ElFormItem label="开始时间"><ElDatePicker v-model="form.startAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" class="full"/></ElFormItem><ElFormItem label="结束时间"><ElDatePicker v-model="form.endAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" class="full"/></ElFormItem><ElFormItem label="说明"><ElInput v-model="form.description" type="textarea"/></ElFormItem></ElForm><template #footer><ElButton @click="dialog=false">取消</ElButton><ElButton type="primary" :loading="saving" @click="save">保存并投放</ElButton></template></ElDialog></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import ResourceHeader from'@/components/plus-resource/ResourceHeader.vue';import{deleteManagedAd,fetchManagedAds,saveManagedAd,type ManagedAdItem}from'@/api/advertisement';const ads=ref<ManagedAdItem[]>([]);const loading=ref(false);const saving=ref(false);const dialog=ref(false);const editing=ref(false);const editingId=ref(0);const form=reactive({adKey:'',title:'',imageUrl:'',destinationUrl:'',position:'home-banner' as 'home-banner'|'sidebar'|'popup',weight:100,startAt:'',endAt:'',description:''});const load=async()=>{loading.value=true;try{ads.value=(await fetchManagedAds()).list||[]}catch(e:any){ElMessage.error(e?.message||'广告加载失败')}finally{loading.value=false}};const reset=()=>Object.assign(form,{adKey:'',title:'',imageUrl:'',destinationUrl:'',position:'home-banner',weight:100,startAt:'',endAt:'',description:''});const openCreate=()=>{editing.value=false;editingId.value=0;reset();dialog.value=true};const edit=(row:ManagedAdItem)=>{editing.value=true;editingId.value=row.id;Object.assign(form,row);dialog.value=true};const save=async()=>{if(!form.adKey||!form.title){ElMessage.warning('请填写广告标识和标题');return};saving.value=true;try{await saveManagedAd({...form,id:editing.value?editingId.value:undefined,published:true});ElMessage.success('广告已保存并投放');dialog.value=false;await load()}catch(e:any){ElMessage.error(e?.message||'保存广告失败')}finally{saving.value=false}};const remove=async(row:ManagedAdItem)=>{try{await ElMessageBox.confirm(`确认删除广告「${row.title}」？`,'删除广告',{type:'warning'});await deleteManagedAd(row.id);ElMessage.success('广告已删除');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e?.message||'删除广告失败')}};onMounted(load)</script>
<style scoped>.resource-page{padding:24px;background:#f6f8fc;min-height:100%;color:#172033}.table-card{margin-top:18px;border:0;border-radius:14px}.ad{display:flex;align-items:center;gap:11px}.ad small{display:block;margin-top:4px;color:#8b94a5;font-size:11px}.thumb{width:36px;height:36px;border-radius:9px;background:linear-gradient(135deg,#7354c8,#d78fb1)}.full{width:100%}.empty{display:flex;align-items:center;flex-direction:column;gap:10px;padding:36px;color:#8b94a5;text-align:center}.empty>svg{font-size:34px;color:#7354c8}.empty strong{color:#172033}@media(max-width:700px){.resource-page{padding:12px}.table-card{overflow-x:auto}}</style>
